static float getSmoothnessCutoffFreq(float baseFreq, int control_smoothness)
{
    uint16_t smoothness = 10 - control_smoothness;
    return 0.001f * baseFreq * (float)(smoothness*smoothness*smoothness) + 0.1f;
}

